python.solution:
def solve(values):
    left, right, count = 0, 1, 0
    while right < len(values):
        gap = values[right] - values[left]
        if gap == 3:
            count += 1
            left += 1
            right += 1
        elif gap < 3:
            right += 1
        else:
            left += 1
        if left == right:
            right += 1
    return count

