function solve(values) {
  let left = 0, right = 1, count = 0;
  while (right < values.length) {
    const gap = values[right] - values[left];
    if (gap === 3) { count++; left++; right++; }
    else if (gap < 3) right++;
    else left++;
    if (left === right) right++;
  }
  return count;
}

