int solve(const int values[], int length) {
  int left = 0, right = 1, count = 0;
  while (right < length) {
    int gap = values[right] - values[left];
    if (gap == 3) { count++; left++; right++; }
    else if (gap < 3) right++; else left++;
    if (left == right) right++;
  }
